content:
ToolResultBlock(tool_use_id='toolu_01BbMrpQPFYy6DAqb6p3tQEN', content='   "field": "type",
   "templates": {
    "credit_card": "credit card ending {card_last4}",
    "personal_loan": "personal loan",
    "car_loan": "car loan"
   }
  },
  "tiers": {
   "field": "days_late",
   "list": [
    {
     "name": "early",
     "min": 1,
     "max": 7,
     "limit": {
      "type": "business_days",
      "n": 12
     },
     "ladder": [
      {
       "text": "{due_m} on {date} [or {floor_m} on {date} if the customer already said the full amount is too much; say that the rest stays overdue]",
       "date": "last_business_day_of_week"
      }
     ]
    },
    {
     "name": "late",
     "min": 8,
     "max": 45,
     "limit": {
      "type": "business_days",
      "n": 7
     },
     "ladder": [
      {
       "text": "{due_m} on {date} [or {floor_m} on {date} if the customer already said the full amount is too much; say that the rest stays overdue]",
       "date": "last_business_day_of_week"
      },
      {
       "text": "{floor_m} on {date} (say that the rest stays overdue)",
       "date": "limit"
      }
     ]
    }
   ]
  },
  "fields": {
   "due": "num(it.get('past_due'))",
   "floor": "first_num(it.get(by_value(it.get('type'), {'credit_card': 'minimum_payment', 'personal_loan': 'instalment_amount', 'car_loan': 'instalment_amount'}, '')), f['due'])",
   "floor_spoken": "by_value(it.get('type'), {'credit_card': 'minimum payment', 'personal_loan': 'instalment amount', 'car_loan': 'instalment amount'}, 'minimum')",
   "deadline": "rule_date(T['limit'], today)"
  },
  "limit_field": "deadline",
  "text": "{n}. product_id {id} = \"{label}\". Past due {due_m}, {days_late} days late. Floor ({floor_spoken}): {floor_m}. Acceptable amount: {floor_m} to {due_m}. Deadline (latest date): {deadline_say} ({deadline_iso}).",
  "ladder": {
   "header": "   OFFER LIST ({n} offer{s}; each refusal moves to the next offer, nothing goes in between):",
   "step": "     offer {k}: {text}",
   "footer": "     after offer {n} is refused: STOP, this product is refused. No floor offer, no other offer."
  },
  "header": "PRODUCTS, in this order:",
  "summary": {
   "line": "Your {label} has a past-due amount of {due_m} and is {days_late} days late.",
   "single": "Thank you, your identity is confirmed. I am calling from the collections team about a late payment. {line} Can you make this payment today?",
   "multi": "Thank you, your identity is confirmed. I am calling from the collections team about late payments on {count} products. {lines} Can you pay all of them today?"
  },
  "facts_var": "item_facts",
  "summary_var": "summary_line"
 },
 "clock": {
  "windows": [
   {
    "var": "callback_facts",
    "intro": "A callback can ONLY be booked on: ",
    "outro": ". Both ends of the time window are included. Any other day or time is outside the window.",
    "start": "10:00",
    "end": "19:00",
    "days": [
     "today",
     "next_business_day"
    ],
    "business_days_only": true
   }
  ]
 },
 "tools": {
  "verify_identity": {
   "role": "verify",
   "description": "Check one security answer. CALL it every time the customer answers a security question, with that one answer.",
   "fields": {
    "field": {
     "description": "Which question this answer is for."
    },
    "answer": {
     "description": "date_of_birth as YYYY-MM-DD (a numbers-only date is day, month, year); phone_last4 as four digits."
    }
   }
  },
  "get_account": {
   "role": "fetch"
  },
  "create_promise": {
   "role": "record",
   "description": "Record one payment promise for one product. CALL it once per product whose promise the customer confirmed in the read-back.",
   "fields": {
    "product_id": {
     "description": "product_id from the PRODUCTS list (p1, p2, ...), copied exactly."
    },
    "amount": {
     "description": "The confirmed amount as a number with two decimals."
    },
    "date": {
     "description": "The confirmed date as YYYY-MM-DD."
    }
   },
   "record": {
    "item_arg": "product_id",
    "noun": "promise",
    "clamp": [
     {
      "arg": "amount",
      "type": "number",
      "max_field": "due"
     },
     {
      "arg": "date",
      "type": "date",
      "business_day": true,
      "max_field": "deadline"
     }
    ],
    "confirm": "{amount} on {date}",
    "confirm_note": "When you tell the customer, use exactly this amount and date.",
    "give_up": "Tell the customer the promise for this product could not be recorded because of a technical problem, then call add_note for this product with reason service_error.",
    "give_up_alone": "Tell the customer the promise could not be recorded because of a technical problem, then call transition_to_end_service_error."
   }
  },
  "schedule_callback": {
   "role": "flag",
   "description": "Book a callback. CALL it as soon as the person gave a day and a time inside the callback window.",
   "fields": {
    "date": {
     "description": "Callback date as YYYY-MM-DD, inside the callback window."
    },
    "time": {
     "description": "Callback time as HH:MM, 24 hour, inside the callback window."
    }
   },
   "flag": {
    "value": "booked",
    "var": "callback_state",
    "ok_text": "The callback is booked.",
    "fail_text": "The callback was NOT booked because the service failed. Try schedule_callback once more with the same values."
   }
  },
  "transfer_to_agent": {
   "role": "flag",
   "description": "Hand the call to a person. CALL it with queue restructuring when the customer asks for a new payment plan or lower instalments; with queue support when a customer in hardship accepts the support team; with queue general when the customer insists on a human.",
   "fields": {
    "queue": {
     "description": "The team that takes over."
    }
   },
   "flag": {
    "value_arg": "queue",
    "ledger_key": "transfer",
    "var": "transfer_queue",
    "ok_text": "The transfer is done.",
    "fail_text": "The transfer did NOT work. Tell the customer you could not transfer the call right now."
   }
  },
  "close_call": {
   "role": "close"
  },
  "add_note": {
